protocol Named { var name: String { get } }
struct Label: Named, Equatable { let name: String }
func uniqueName<T>(_ value: T, in values: [T]) -> String?
where T: Named, T: Equatable {
    values.contains(value) ? value.name : nil
}
print(uniqueName(Label(name: "Север"), in: [Label(name: "Север")]) ?? "Нет")

Для Label(name: Север) в таком же списке получаем Север; пустой массив даёт nil.

