key:
struct Recent<Value> {
    private(set) var values: [Value] = []
    mutating func push(_ value: Value) { values.append(value) }
}
extension Recent where Value: Equatable {
    mutating func pushUnique(_ value: Value) {
        guard !values.contains(value) else { return }
        push(value)
    }
}

После двух pushUnique("Тонкая") массив содержит одну строку. Уникальность — условная способность, не ограничение основного хранилища.
